#!/usr/bin/env bash
set -euo pipefail

BRANCH="feature/kosmora-relay-release-acceptance"
BASE_COMMIT="90e50e2924a5d99366cc89669f1ea61ec92a88cc"

echo "==> Проверка репозитория Kosmora / Nexus-OS..."
git fetch origin main --tags || true

if git cat-file -e "${BASE_COMMIT}^{commit}" 2>/dev/null; then
  git checkout -B "${BRANCH}" "${BASE_COMMIT}"
else
  git checkout -B "${BRANCH}" origin/main
fi

TMP_PATCH="$(mktemp)"
trap "rm -f \"${TMP_PATCH}\"" EXIT

base64 -d <<'EOF_PATCH_B64' > "${TMP_PATCH}"

EOF_PATCH_B64

echo "==> Применение патча ${BRANCH}..."
git am --3way "${TMP_PATCH}"

echo "==> Запуск проверок..."
node scripts/check-secrets.mjs
git diff --check

echo "==> Отправка ветки ${BRANCH} в origin..."
git push -u origin "${BRANCH}"
echo "==> Готово! Ветка ${BRANCH} опубликована."